<?php
require __DIR__ . '/auth/bootstrap.php';
zuri_require_login();
$stmt = $pdo->prepare('SELECT full_name,email,phone,created_at FROM zuri_users WHERE id = ? AND is_active = 1 LIMIT 1');
$stmt->execute([(int)$_SESSION['zuri_user_id']]);
$account = $stmt->fetch();
if (!$account) { $_SESSION = []; session_destroy(); header('Location: login.php'); exit; }
